from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    marker = min(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    shape = [(r-r0, c-c0) for r,c in pts]
    out = [row[:] for row in grid]
    for r in range(h-(r1-r0)):
        for c in range(w-(c1-c0)):
            if all(grid[r+dr][c+dc] == 0 for dr,dc in shape):
                for dr,dc in shape:
                    out[r+dr][c+dc] = marker
    return out
